INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_12a_answer','{"en": "Answer to a complaint", "ru": "Ответ на исковое заявление"}'::jsonb,21,'day','calendar','after',NULL,'FRCP 12(a)(1)(A)(i)','{"en": "Counted from the day after service. If service was waived the time is 60 days; for the United States it is 60 days.", "ru": "Отсчёт со дня после вручения. При отказе от вручения срок 60 дней; для США — 60 дней."}'::jsonb,false,true,10,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_12a_waiver','{"en": "Answer after a waiver of service", "ru": "Ответ после отказа от вручения"}'::jsonb,60,'day','calendar','after',NULL,'FRCP 12(a)(1)(A)(ii)','{"en": "Counted from the day the request for waiver was sent; 90 days if it was sent outside the United States.", "ru": "Отсчёт со дня отправки запроса; 90 дней, если отправлен за пределы США."}'::jsonb,false,true,11,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_12a2_us','{"en": "Answer by the United States", "ru": "Ответ от имени США"}'::jsonb,60,'day','calendar','after',NULL,'FRCP 12(a)(2)','{"en": "Counted from service on the United States attorney.", "ru": "Отсчёт со дня вручения прокурору США."}'::jsonb,false,true,12,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_15a1_amend','{"en": "Amend a pleading once as of right", "ru": "Изменить иск один раз без разрешения"}'::jsonb,21,'day','calendar','after',NULL,'FRCP 15(a)(1)','{"en": "Counted from service of the pleading, or from service of a response or a Rule 12(b) motion, whichever is earlier.", "ru": "Отсчёт со дня вручения иска либо ответа или ходатайства по правилу 12(b) — что раньше."}'::jsonb,false,true,13,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_discovery_30','{"en": "Respond to discovery requests", "ru": "Ответ на запросы раскрытия"}'::jsonb,30,'day','calendar','after',NULL,'FRCP 33(b)(2), 34(b)(2)(A), 36(a)(3)','{"en": "Interrogatories, document requests and requests for admission. An unanswered request for admission is deemed admitted.", "ru": "Вопросы, запросы документов и признания фактов. Неотвеченный запрос о признании считается признанным."}'::jsonb,false,true,14,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_59_new_trial','{"en": "Motion for a new trial or to amend a judgment", "ru": "Ходатайство о новом рассмотрении или изменении решения"}'::jsonb,28,'day','calendar','after',NULL,'FRCP 50(b), 52(b), 59(b), 59(e)','{"en": "The court cannot extend this time.", "ru": "Суд не может продлить этот срок."}'::jsonb,false,true,15,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frcp_6c_motion','{"en": "Serve a motion before the hearing", "ru": "Подать ходатайство до заседания"}'::jsonb,14,'day','calendar','before',NULL,'FRCP 6(c)(1)(A)','{"en": "Counted backward from the hearing date.", "ru": "Отсчёт назад от даты заседания."}'::jsonb,false,true,16,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
