INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','frap_4a1a_appeal','{"en": "Notice of appeal (civil case)", "ru": "Уведомление об апелляции (гражданское дело)"}'::jsonb,30,'day','calendar','after',NULL,'FRAP 4(a)(1)(A)','{"en": "Counted from entry of the judgment or order.", "ru": "Отсчёт со дня внесения решения или определения."}'::jsonb,false,true,20,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
