INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','usc_1446_removal','{"en": "Remove a case to federal court", "ru": "Перевод дела в федеральный суд"}'::jsonb,30,'day','calendar','after',NULL,'28 U.S.C. § 1446(b)(1)','{"en": "Counted from receipt of the initial pleading through service.", "ru": "Отсчёт со дня получения иска при вручении."}'::jsonb,false,true,23,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
