INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','bia_appeal_30','{"en": "Appeal to the Board of Immigration Appeals", "ru": "Апелляция в Совет по апелляциям (BIA)"}'::jsonb,30,'day','calendar','after','immigration','8 C.F.R. § 1003.38(b)','{"en": "Counted from the immigration judge''s decision (oral decision: the day it is given).", "ru": "Отсчёт со дня решения судьи (устное решение — со дня оглашения)."}'::jsonb,false,true,30,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','ina_pfr_30','{"en": "Petition for review of a removal order", "ru": "Ходатайство о пересмотре приказа о высылке"}'::jsonb,30,'day','calendar','after','immigration','8 U.S.C. § 1252(b)(1)','{"en": "Counted from the final order. The time is jurisdictional and cannot be extended.", "ru": "Отсчёт с окончательного приказа. Срок не продлевается."}'::jsonb,false,true,31,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','ina_reopen_90','{"en": "Motion to reopen (immigration court)", "ru": "Ходатайство о возобновлении дела (иммиграционный суд)"}'::jsonb,90,'day','calendar','after','immigration','8 C.F.R. § 1003.23(b)(1)','{"en": "Exceptions exist (for example in absentia orders and asylum changes).", "ru": "Есть исключения (например, заочные приказы)."}'::jsonb,false,true,32,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
