INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','irc_6213_tax_court','{"en": "Tax Court petition after a notice of deficiency", "ru": "Иск в налоговый суд после уведомления о недоимке"}'::jsonb,90,'day','calendar','after','tax_law','26 U.S.C. § 6213(a)','{"en": "Counted from the day the notice was mailed; 150 days if it is addressed outside the United States.", "ru": "Отсчёт со дня отправки уведомления; 150 дней, если адрес за пределами США."}'::jsonb,false,true,40,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','court_deadline','ss_reconsideration_60','{"en": "Social Security: request reconsideration", "ru": "Социальное обеспечение: запрос пересмотра"}'::jsonb,60,'day','calendar','after','social_security_disability','20 C.F.R. § 404.909(a)','{"en": "Counted from receipt of the notice. Receipt is presumed 5 days after the date on the notice.", "ru": "Отсчёт с получения уведомления. Получение считается через 5 дней после даты на уведомлении."}'::jsonb,false,true,50,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
