INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','statute_of_limitations','eeoc_charge_180','{"en": "File a discrimination charge with the EEOC", "ru": "Жалоба о дискриминации в EEOC"}'::jsonb,180,'day','calendar','after','employment_and_labor','42 U.S.C. § 2000e-5(e)(1)','{"en": "Counted from the unlawful act. 300 days in a state with its own fair-employment agency.", "ru": "Отсчёт с неправомерного действия. 300 дней в штате со своим агентством по трудовой дискриминации."}'::jsonb,false,true,60,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
