INSERT INTO "deadline_rules" ("jurisdiction","kind","code","labels","amount","unit","day_type","direction","practice_code","citation","notes","verified","is_active","sort","updated_at") VALUES ('US','statute_of_limitations','ftca_claim_2y','{"en": "Federal Tort Claims Act: file the administrative claim", "ru": "Иск к государству (FTCA): подать претензию"}'::jsonb,2,'year','calendar','after','government_and_administrative_law','28 U.S.C. § 2401(b)','{"en": "Counted from when the claim accrues. Suit must follow within 6 months of the agency''s denial.", "ru": "Отсчёт с возникновения требования. Иск — в течение 6 месяцев после отказа ведомства."}'::jsonb,false,true,63,CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
